// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// EbayDeletionChallenge Answer eBay's check that this notification endpoint is ours
	// (GET /ebay/account-deletion)
	EbayDeletionChallenge(ctx context.Context, request EbayDeletionChallengeRequestObject) (EbayDeletionChallengeResponseObject, error)
	// EbayAccountDeletion Forget an eBay user who closed their account
	// (POST /ebay/account-deletion)
	EbayAccountDeletion(ctx context.Context, request EbayAccountDeletionRequestObject) (EbayAccountDeletionResponseObject, error)
	// SearchEbay Search eBay without saving anything
	// (GET /ebay/search)
	SearchEbay(ctx context.Context, request SearchEbayRequestObject) (SearchEbayResponseObject, error)
	// GetListing One stored listing, its price history, and the searches that found it
	// (GET /listings/{listingId})
	GetListing(ctx context.Context, request GetListingRequestObject) (GetListingResponseObject, error)
	// SetMatchStatus Mark matches seen, starred, dismissed, or new again
	// (POST /matches/status)
	SetMatchStatus(ctx context.Context, request SetMatchStatusRequestObject) (SetMatchStatusResponseObject, error)
	// GetMe The api key this request acts as
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListRuns Recent runs, newest first, a page at a time
	// (GET /runs)
	ListRuns(ctx context.Context, request ListRunsRequestObject) (ListRunsResponseObject, error)
	// ListSearches List saved searches, newest first, a page at a time
	// (GET /searches)
	ListSearches(ctx context.Context, request ListSearchesRequestObject) (ListSearchesResponseObject, error)
	// CreateSearch Save a search
	// (POST /searches)
	CreateSearch(ctx context.Context, request CreateSearchRequestObject) (CreateSearchResponseObject, error)
	// DeleteSearch Delete a saved search
	// (DELETE /searches/{searchId})
	DeleteSearch(ctx context.Context, request DeleteSearchRequestObject) (DeleteSearchResponseObject, error)
	// GetSearch One saved search
	// (GET /searches/{searchId})
	GetSearch(ctx context.Context, request GetSearchRequestObject) (GetSearchResponseObject, error)
	// UpdateSearch Change a saved search
	// (PATCH /searches/{searchId})
	UpdateSearch(ctx context.Context, request UpdateSearchRequestObject) (UpdateSearchResponseObject, error)
	// ListMatches A search's matches, newest first, a page at a time
	// (GET /searches/{searchId}/matches)
	ListMatches(ctx context.Context, request ListMatchesRequestObject) (ListMatchesResponseObject, error)
	// RunSearch Run a saved search against eBay now
	// (POST /searches/{searchId}/run)
	RunSearch(ctx context.Context, request RunSearchRequestObject) (RunSearchResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

